pub const Tensor = struct {
     []f32,
    shape: []const usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, shape: []const usize) !Tensor {
        var size: usize = 1;
        for (shape) |d| size *= d;
        const data = try allocator.alloc(f32, size);
        return Tensor{ .data = data, .shape = try allocator.dupe(usize, shape), .allocator = allocator };
    }

    pub fn deinit(self: *const Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
    }
};

pub const ThreadPool = struct {
    threads: []std.Thread,
    tasks: std.fifo.LinearFifo(Task, .Dynamic),
    mutex: std.Thread.Mutex,
    condition: std.Thread.Condition,
    allocator: std.mem.Allocator,
    shutdown: bool,

    const Task = struct {
        func: *const fn (*anyopaque) void,
        ctx: *anyopaque,
    };

    pub fn init(allocator: std.mem.Allocator, num_threads: usize) !*ThreadPool {
        var pool = try allocator.create(ThreadPool);
        pool.allocator = allocator;
        pool.tasks = std.fifo.LinearFifo(Task, .Dynamic).init(allocator);
        pool.mutex = std.Thread.Mutex{};
        pool.condition = std.Thread.Condition{};
        pool.shutdown = false;
        pool.threads = try allocator.alloc(std.Thread, num_threads);

        var i: usize = 0;
        while (i < num_threads) : (i += 1) {
            pool.threads[i] = try std.Thread.spawn(.{}, workerLoop, .{pool});
        }
        return pool;
    }

    pub fn deinit(self: *ThreadPool) void {
        self.mutex.lock();
        self.shutdown = true;
        self.mutex.unlock();
        self.condition.broadcast();

        for (self.threads) |thread| {
            thread.join();
        }

        self.allocator.free(self.threads);
        self.tasks.deinit();
        self.allocator.destroy(self);
    }

    pub fn enqueue(self: *ThreadPool, func: *const fn (*anyopaque) void, ctx: *anyopaque) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        try self.tasks.writeItem(Task{ .func = func, .ctx = ctx });
        self.condition.signal();
    }

    fn workerLoop(self: *ThreadPool) void {
        while (true) {
            self.mutex.lock();
            while (self.tasks.readableLength() == 0 and !self.shutdown) {
                self.condition.wait(&self.mutex);
            }
            if (self.shutdown and self.tasks.readableLength() == 0) {
                self.mutex.unlock();
                break;
            }
            const task = self.tasks.readItem().?;
            self.mutex.unlock();
            task.func(task.ctx);
        }
    }
};

pub const ROSFConfig = struct {
    learning_rate: f32 = 0.02,
    momentum: f32 = 0.95,
    ns_steps: usize = 5,
    block_size: usize = 64,
    threads: usize = 16,
};

const MatmulTaskCtx = struct {
    dim: usize,
    a: [*]const f32,
    b: [*]const f32,
    out: [*]f32,
    start_row: usize,
    end_row: usize,
    block_size: usize,
    wait_group: *std.Thread.WaitGroup,
};

const TransposeTaskCtx = struct {
    dim: usize,
    in: [*]const f32,
    out: [*]f32,
    start_row: usize,
    end_row: usize,
    block_size: usize,
    wait_group: *std.Thread.WaitGroup,
};

const OrthoUpdateTaskCtx = struct {
    len: usize,
    x: [*]f32,
    b_mat: [*]const f32,
    start_idx: usize,
    end_idx: usize,
    wait_group: *std.Thread.WaitGroup,
};

pub const ROSFOptimizer = struct {
    allocator: std.mem.Allocator,
    config: ROSFConfig,
    thread_pool: *ThreadPool,
    momentum_s: Tensor,
    momentum_t: Tensor,
    temp_x: Tensor,
    temp_xt: Tensor,
    temp_a: Tensor,
    temp_b: Tensor,

    pub fn init(allocator: std.mem.Allocator, dim: usize, config: ROSFConfig) !*ROSFOptimizer {
        var opt = try allocator.create(ROSFOptimizer);
        opt.allocator = allocator;
        opt.config = config;
        opt.thread_pool = try ThreadPool.init(allocator, config.threads);

        const shape = &[_]usize{ dim, dim };
        opt.momentum_s = try Tensor.init(allocator, shape);
        opt.momentum_t = try Tensor.init(allocator, shape);
        opt.temp_x = try Tensor.init(allocator, shape);
        opt.temp_xt = try Tensor.init(allocator, shape);
        opt.temp_a = try Tensor.init(allocator, shape);
        opt.temp_b = try Tensor.init(allocator, shape);

        @memset(opt.momentum_s.data, 0.0);
        @memset(opt.momentum_t.data, 0.0);
        @memset(opt.temp_x.data, 0.0);
        @memset(opt.temp_xt.data, 0.0);
        @memset(opt.temp_a.data, 0.0);
        @memset(opt.temp_b.data, 0.0);

        return opt;
    }

    pub fn deinit(self: *ROSFOptimizer) void {
        self.momentum_s.deinit();
        self.momentum_t.deinit();
        self.temp_x.deinit();
        self.temp_xt.deinit();
        self.temp_a.deinit();
        self.temp_b.deinit();
        self.thread_pool.deinit();
        self.allocator.destroy(self);
    }

    fn matmulWorker(ctx_raw: *anyopaque) void {
        const ctx = @as(*MatmulTaskCtx, @ptrCast(@alignCast(ctx_raw)));
        const dim = ctx.dim;
        const bs = ctx.block_size;
        var i = ctx.start_row;
        while (i < ctx.end_row) : (i += bs) {
            const i_end = @min(i + bs, ctx.end_row);
            var k: usize = 0;
            while (k < dim) : (k += bs) {
                const k_end = @min(k + bs, dim);
                var j: usize = 0;
                while (j < dim) : (j += bs) {
                    const j_end = @min(j + bs, dim);
                    var ii = i;
                    while (ii < i_end) : (ii += 1) {
                        var kk = k;
                        while (kk < k_end) : (kk += 1) {
                            const a_val = ctx.a[ii * dim + kk];
                            const v_a = @as(@Vector(8, f32), @splat(a_val));
                            var jj = j;
                            while (jj + 8 <= j_end) : (jj += 8) {
                                const b_vec: @Vector(8, f32) = ctx.b[(kk * dim + jj)..(kk * dim + jj + 8)].*;
                                var out_vec: @Vector(8, f32) = ctx.out[(ii * dim + jj)..(ii * dim + jj + 8)].*;
                                out_vec += v_a * b_vec;
                                @memcpy(ctx.out[(ii * dim + jj)..(ii * dim + jj + 8)], @as([8]f32, out_vec)[0..8]);
                            }
                            while (jj < j_end) : (jj += 1) {
                                ctx.out[ii * dim + jj] += a_val * ctx.b[kk * dim + jj];
                            }
                        }
                    }
                }
            }
        }
        ctx.wait_group.finish();
        std.heap.page_allocator.destroy(ctx);
    }

    fn transposeWorker(ctx_raw: *anyopaque) void {
        const ctx = @as(*TransposeTaskCtx, @ptrCast(@alignCast(ctx_raw)));
        const dim = ctx.dim;
        const bs = ctx.block_size;
        var i = ctx.start_row;
        while (i < ctx.end_row) : (i += bs) {
            const i_end = @min(i + bs, ctx.end_row);
            var j: usize = 0;
            while (j < dim) : (j += bs) {
                const j_end = @min(j + bs, dim);
                var ii = i;
                while (ii < i_end) : (ii += 1) {
                    var jj = j;
                    while (jj < j_end) : (jj += 1) {
                        ctx.out[jj * dim + ii] = ctx.in[ii * dim + jj];
                    }
                }
            }
        }
        ctx.wait_group.finish();
        std.heap.page_allocator.destroy(ctx);
    }

    fn orthoUpdateWorker(ctx_raw: *anyopaque) void {
        const ctx = @as(*OrthoUpdateTaskCtx, @ptrCast(@alignCast(ctx_raw)));
        var idx = ctx.start_idx;
        while (idx + 8 <= ctx.end_idx) : (idx += 8) {
            var v_x: @Vector(8, f32) = ctx.x[idx..(idx + 8)].*;
            const v_b: @Vector(8, f32) = ctx.b_mat[idx..(idx + 8)].*;
            const v_1_5 = @as(@Vector(8, f32), @splat(1.5));
            const v_0_5 = @as(@Vector(8, f32), @splat(0.5));
            v_x = (v_1_5 * v_x) - (v_0_5 * v_b);
            @memcpy(ctx.x[idx..(idx + 8)], @as([8]f32, v_x)[0..8]);
        }
        while (idx < ctx.end_idx) : (idx += 1) {
            ctx.x[idx] = 1.5 * ctx.x[idx] - 0.5 * ctx.b_mat[idx];
        }
        ctx.wait_group.finish();
        std.heap.page_allocator.destroy(ctx);
    }

    fn dispatchMatmul(self: *ROSFOptimizer, dim: usize, a: [*]const f32, b: [*]const f32, out: [*]f32) !void {
        @memset(out[0..(dim * dim)], 0.0);
        var wg = std.Thread.WaitGroup{};
        const rows_per_thread = (dim + self.config.threads - 1) / self.config.threads;
        var r: usize = 0;
        while (r < dim) : (r += rows_per_thread) {
            const end_r = @min(r + rows_per_thread, dim);
            var ctx = try std.heap.page_allocator.create(MatmulTaskCtx);
            ctx.* = .{
                .dim = dim,
                .a = a,
                .b = b,
                .out = out,
                .start_row = r,
                .end_row = end_r,
                .block_size = self.config.block_size,
                .wait_group = &wg,
            };
            wg.start();
            try self.thread_pool.enqueue(matmulWorker, ctx);
        }
        wg.wait();
    }

    fn dispatchTranspose(self: *ROSFOptimizer, dim: usize, in: [*]const f32, out: [*]f32) !void {
        var wg = std.Thread.WaitGroup{};
        const rows_per_thread = (dim + self.config.threads - 1) / self.config.threads;
        var r: usize = 0;
        while (r < dim) : (r += rows_per_thread) {
            const end_r = @min(r + rows_per_thread, dim);
            var ctx = try std.heap.page_allocator.create(TransposeTaskCtx);
            ctx.* = .{
                .dim = dim,
                .in = in,
                .out = out,
                .start_row = r,
                .end_row = end_r,
                .block_size = self.config.block_size,
                .wait_group = &wg,
            };
            wg.start();
            try self.thread_pool.enqueue(transposeWorker, ctx);
        }
        wg.wait();
    }

    fn dispatchOrthoUpdate(self: *ROSFOptimizer, len: usize, x: [*]f32, b_mat: [*]const f32) !void {
        var wg = std.Thread.WaitGroup{};
        const items_per_thread = (len + self.config.threads - 1) / self.config.threads;
        var idx: usize = 0;
        while (idx < len) : (idx += items_per_thread) {
            const end_idx = @min(idx + items_per_thread, len);
            var ctx = try std.heap.page_allocator.create(OrthoUpdateTaskCtx);
            ctx.* = .{
                .len = len,
                .x = x,
                .b_mat = b_mat,
                .start_idx = idx,
                .end_idx = end_idx,
                .wait_group = &wg,
            };
            wg.start();
            try self.thread_pool.enqueue(orthoUpdateWorker, ctx);
        }
        wg.wait();
    }

    fn frobeniusNorm( []const f32) f32 {
        var sum: f32 = 0.0;
        var i: usize = 0;
        while (i + 8 <= data.len) : (i += 8) {
            const v: @Vector(8, f32) = data[i..(i + 8)].*;
            const sq = v * v;
            sum += @reduce(.Add, sq);
        }
        while (i < data.len) : (i += 1) {
            sum += data[i] * data[i];
        }
        return @sqrt(sum) + 1e-8;
    }

    fn orthogonalize(self: *ROSFOptimizer, dim: usize, grad: []f32) !void {
        const norm = frobeniusNorm(grad);
        const inv_norm = 1.0 / norm;
        var i: usize = 0;
        while (i + 8 <= grad.len) : (i += 8) {
            var v: @Vector(8, f32) = grad[i..(i + 8)].*;
            v *= @as(@Vector(8, f32), @splat(inv_norm));
            @memcpy(self.temp_x.data[i..(i + 8)], @as([8]f32, v)[0..8]);
        }
        while (i < grad.len) : (i += 1) {
            self.temp_x.data[i] = grad[i] * inv_norm;
        }

        var step: usize = 0;
        while (step < self.config.ns_steps) : (step += 1) {
            try self.dispatchTranspose(dim, self.temp_x.data.ptr, self.temp_xt.data.ptr);
            try self.dispatchMatmul(dim, self.temp_x.data.ptr, self.temp_xt.data.ptr, self.temp_a.data.ptr);
            try self.dispatchMatmul(dim, self.temp_a.data.ptr, self.temp_x.data.ptr, self.temp_b.data.ptr);
            try self.dispatchOrthoUpdate(grad.len, self.temp_x.data.ptr, self.temp_b.data.ptr);
        }

        var k: usize = 0;
        while (k + 8 <= grad.len) : (k += 8) {
            var v: @Vector(8, f32) = self.temp_x.data[k..(k + 8)].*;
            v *= @as(@Vector(8, f32), @splat(norm));
            @memcpy(grad[k..(k + 8)], @as([8]f32, v)[0..8]);
        }
        while (k < grad.len) : (k += 1) {
            grad[k] = self.temp_x.data[k] * norm;
        }
    }

    pub fn step(self: *ROSFOptimizer, weight_s: *Tensor, weight_t: *Tensor, grad_s: *const Tensor, grad_t: *const Tensor) !void {
        const dim = weight_s.shape[0];
        const len = weight_s.data.len;
        const lr = self.config.learning_rate;
        const mu = self.config.momentum;

        var i: usize = 0;
        while (i + 8 <= len) : (i += 8) {
            var ms_vec: @Vector(8, f32) = self.momentum_s.data[i..(i + 8)].*;
            var mt_vec: @Vector(8, f32) = self.momentum_t.data[i..(i + 8)].*;
            const gs_vec: @Vector(8, f32) = grad_s.data[i..(i + 8)].*;
            const gt_vec: @Vector(8, f32) = grad_t.data[i..(i + 8)].*;
            const v_mu = @as(@Vector(8, f32), @splat(mu));
            const v_1_mu = @as(@Vector(8, f32), @splat(1.0 - mu));

            ms_vec = (v_mu * ms_vec) + (v_1_mu * gs_vec);
            mt_vec = (v_mu * mt_vec) + (v_1_mu * gt_vec);

            @memcpy(self.momentum_s.data[i..(i + 8)], @as([8]f32, ms_vec)[0..8]);
            @memcpy(self.momentum_t.data[i..(i + 8)], @as([8]f32, mt_vec)[0..8]);
        }
        while (i < len) : (i += 1) {
            self.momentum_s.data[i] = mu * self.momentum_s.data[i] + (1.0 - mu) * grad_s.data[i];
            self.momentum_t.data[i] = mu * self.momentum_t.data[i] + (1.0 - mu) * grad_t.data[i];
        }

        @memcpy(self.temp_a.data[0..len], self.momentum_s.data[0..len]);
        @memcpy(self.temp_b.data[0..len], self.momentum_t.data[0..len]);

        try self.orthogonalize(dim, self.temp_a.data);
        try self.orthogonalize(dim, self.temp_b.data);

        var j: usize = 0;
        while (j + 8 <= len) : (j += 8) {
            var ws_vec: @Vector(8, f32) = weight_s.data[j..(j + 8)].*;
            var wt_vec: @Vector(8, f32) = weight_t.data[j..(j + 8)].*;
            const a_vec: @Vector(8, f32) = self.temp_a.data[j..(j + 8)].*;
            const b_vec: @Vector(8, f32) = self.temp_b.data[j..(j + 8)].*;
            const v_lr = @as(@Vector(8, f32), @splat(lr));

            ws_vec -= v_lr * a_vec;
            wt_vec -= v_lr * b_vec;

            @memcpy(weight_s.data[j..(j + 8)], @as([8]f32, ws_vec)[0..8]);
            @memcpy(weight_t.data[j..(j + 8)], @as([8]f32, wt_vec)[0..8]);
        }
        while (j < len) : (j += 1) {
            weight_s.data[j] -= lr * self.temp_a.data[j];
            weight_t.data[j] -= lr * self.temp_b.data[j];
        }
    }
};

